<template><div><PageHeader title="Courses" description="Create and manage your training catalog, curriculum and materials."><template #actions><button class="btn secondary">Import</button><RouterLink to="/app/courses/create" class="btn primary">+ Create course</RouterLink></template></PageHeader><div class="toolbar card" style="margin-bottom:16px"><div class="toolbar-left"><input v-model="q" class="input search-input" placeholder="Search courses..."><select class="select" v-model="filter"><option value="all">All status</option><option>active</option><option>draft</option></select></div><div class="section-note">{{filtered.length}} courses</div></div><div class="course-grid"><article v-for="course in filtered" :key="course.id" class="course-card"><div class="course-top"><div class="course-icon">{{course.code.slice(0,1)}}</div><StatusBadge :status="course.status"/></div><h3>{{course.name}}</h3><p>{{course.code}} · {{course.category}}</p><div class="course-meta"><span>◷ {{course.duration}}h</span><span>▦ {{course.modules}} modules</span><span>◌ {{course.learners}}</span></div><div class="course-bottom"><div class="course-bottom-line"><span>Completion</span><strong>{{course.completion}}%</strong></div><div class="progress"><span :style="{width:`${course.completion}%`}"></span></div><RouterLink class="btn secondary small" style="width:100%;margin-top:14px" :to="`/app/courses/${course.id}`">Open course</RouterLink></div></article></div></div></template>
<script setup lang="ts">import {computed,ref} from 'vue';import PageHeader from '../components/PageHeader.vue';import StatusBadge from '../components/StatusBadge.vue';import {courses} from '../data/mock';const q=ref(''),filter=ref('all');const filtered=computed(()=>courses.filter(c=>(filter.value==='all'||c.status===filter.value)&&`${c.name} ${c.code} ${c.category}`.toLowerCase().includes(q.value.toLowerCase())))</script>
